solution.code:
// Petición a una REST API privada (identificador a1b2c3d4e5) por el nombre DNS público
// de un VPC endpoint de interfaz con el DNS privado desactivado: ahora identifica la API.
export const peticion = {
  metodo: "GET",
  url: "https://vpce-0a1b2c3d4e5f60718-ab12cd34.execute-api.eu-west-1.vpce.amazonaws.com/prod/pedidos/42",
  cabeceras: {
    Accept: "application/json",
    "x-apigw-api-id": "a1b2c3d4e5",
  },
};

spec.code:
const valor = peticion.cabeceras["x-apigw-api-id"];
assert.strictEqual(typeof valor, "string");
assert.strictEqual(valor, valor.trim());
assert.match(valor, /^[a-z0-9]{10}$/);

assert.ok(!("cuerpo" in peticion), "una petición GET de lectura no lleva cuerpo");
const nombres = Object.keys(peticion.cabeceras).map((nombre) => nombre.toLowerCase());
assert.ok(!nombres.some((nombre) => /authorization|secret|token|key/.test(nombre)), "no se pegan credenciales en la petición");

