// Debe permitir invocar la API solo desde el VPC endpoint vpce-0a1b2c3d4e5f60718.
export const politica = {
  Version: "2012-10-17",
  Statement: [
    {
      Effect: "Allow",
      Principal: "*",
      Action: "execute-api:Invoke",
      Resource: "execute-api:/*",
      Condition: {
        StringEquals: {
          "aws:SourceVpc": "vpce-0a1b2c3d4e5f60718",
        },
      },
    },
  ],
};

solution.code:
// Política de recurso de una REST API privada, escrita como objeto JSON.
// Debe permitir invocar la API solo desde el VPC endpoint vpce-0a1b2c3d4e5f60718.
export const politica = {
  Version: "2012-10-17",
  Statement: [
    {
      Effect: "Allow",
      Principal: "*",
      Action: "execute-api:Invoke",
      Resource: "execute-api:/*",
      Condition: {
        StringEquals: {
          "aws:SourceVpce": "vpce-0a1b2c3d4e5f60718",
        },
      },
    },
  ],
};

spec.code:
const sentencia = politica.Statement[0];
assert.strictEqual(politica.Version, "2012-10-17");
assert.strictEqual(sentencia.Effect, "Allow");
assert.strictEqual(sentencia.Action, "execute-api:Invoke");
assert.strictEqual(sentencia.Resource, "execute-api:/*");
